const inputJson = $input.item.json;

if (Array.isArray(inputJson) && inputJson.length > 0 && inputJson[0].data) {
  campaigns = inputJson[0].data;
} else if (inputJson && inputJson.data) {
  campaigns = inputJson.data;
}

if (campaigns.length === 0) {
  return [{
    json: {
      estado_general: "Sin Datos",
      reporte_final: "No se encontraron campañas para analizar en la entrada de datos."
    }
  }];
}

const reportParts = [];

for (const campaign of campaigns) {
