  fechaLimite.setDate(ahora.getDate() - UMBRALES.DIAS_MIN_ANTIGUEDAD);

  if (fechaCreacion >= fechaLimite) {
    estadoFinal = 'Fuera de pool de alertas';
  } else {
    const metrics = campaign.insights?.data[0];
    if (!metrics) {
      estadoFinal = 'REQUIERE REVISIÓN';
      motivoFinal = 'No se encontraron datos de métricas. Posible error de entrega.';
    } else {
      let esCampanaAnalizable = false;
      if (metrics.cost_per_result && metrics.cost_per_result.length > 0) {
