    const campaignReport = `Campaña: ${campaign.name}
Fecha de creación: ${fechaFormateada}
Estado: ${estadoFinal}
Razón: ${motivoFinal}
---------------`;
    reportParts.push(campaignReport);
  }
}

// --- 3. ENSAMBLAJE FINAL DEL REPORTE ---
let finalReport = "";
let estadoGeneral = "";

if (reportParts.length > 0) {
  estadoGeneral = "Reporte Existente";
  finalReport = `//////////////////////////////////////////////////////////////////////////////
Cliente: ${nombreCliente}
Empresa: ${nombreEmpresa}
ID Cuenta Publicitaria: ${idCuentaPublicitaria}
---------------
${reportParts.join('\n')}`;
} else {
  estadoGeneral = "Todo OK";
  finalReport = `Todas las campañas para ${nombreEmpresa} están dentro de los umbrales correctos.`;
}

return [{
  json: {
    estado_general: estadoGeneral,
    reporte_final: finalReport
  }
}];

