const incomingItems = $input.all();
const requiredColumnIds = ['text8', 'estado__1', 'text_mksx2nnx'];

const formattedItems = incomingItems.map(item => {
  const mondayItem = item.json;

  const filteredAndSimplifiedColumns = mondayItem.column_values
    .filter(column => requiredColumnIds.includes(column.id))
    .map(column => ({
      id: column.id,
      text: column.text
    }));

  // Formato limpio sin la clave vacía.
  const desiredFormat = {
    "data": {
      "id": mondayItem.id,
      "name": mondayItem.name,
      "column_values": filteredAndSimplifiedColumns
    }
  };

  return {
    json: desiredFormat
  };
});

return formattedItems;
